<?php
declare(strict_types=1);
define('MK_INTERNAL',true);define('MK_COMMERCE_TEST_DB',':memory:');require dirname(__DIR__).'/site-deploy/meinkraut/server/commerce.php';
function check($condition,string $name): void{if(!$condition)throw new RuntimeException($name);}
$root=dirname(__DIR__).'/site-deploy/meinkraut';$paths=['/','/gewuerz/schwarzer-pfeffer/','/mischung/mk-steakpfeffer/','/mischungen/','/gewuerze/','/produkt/pfeffer-schwarz/','/land/DE/','/gewuerzshop/','/premium/','/etiketten/','/warenkorb/','/konto/'];
foreach($paths as $path){$_SERVER['REQUEST_URI']=$path;$_GET=[];$c=mk_public_context();check($c['status']===200,'route '.$path);$body=mk_public_body($c);check(substr_count($body,'<h1')===1,'one H1 '.$path);check($c['canonical']==='https://meinkraut.odpc.de'.$path,'canonical '.$path);check(strlen($c['description'])>20,'description '.$path);check($c['noindex']===in_array($path,['/etiketten/','/warenkorb/','/konto/']),'index policy '.$path);}
$_SERVER['REQUEST_URI']='/mischung/not-a-recipe/';check(mk_public_context()['status']===404,'unknown recipe404');
$_SERVER['REQUEST_URI']='/mischungen/?seite=999';$_GET=['seite'=>'999'];check(mk_public_context()['status']===404,'out-of-range pagination404');$_GET=[];
$xml=file_get_contents($root.'/sitemap.xml');preg_match_all('~<loc>https://meinkraut.odpc.de([^<]+)</loc>~',$xml,$matches);check(count($matches[1])===count(array_unique($matches[1]))&&count($matches[1])>900,'sitemap unique and complete');foreach($matches[1] as $path){$_SERVER['REQUEST_URI']=$path;$c=mk_public_context();check($c['status']===200&&!$c['noindex'],'indexable sitemap '.$path);check($c['canonical']==='https://meinkraut.odpc.de'.$path,'sitemap canonical '.$path);}
$manifest=json_decode(file_get_contents(dirname(__DIR__).'/deployment/meinkraut-catalog-release.json'),true);
foreach($manifest['addedRecipes'] as $rid){$_SERVER['REQUEST_URI']='/mischung/'.$rid.'/';$c=mk_public_context();check($c['status']===200,'new recipe route');$body=mk_public_body($c);check(str_contains($body,$c['item']['sources'][0]['url'])&&str_contains($body,$c['item']['sources'][0]['author']),'recipe attribution');foreach($c['item']['allergens']??[] as $allergen)check(str_contains($body,$allergen),'allergen note');check(!str_contains($body,'Eigene Hausvariante; keine garantierte Markenrezeptur'),'no false author label');}
foreach($manifest['addedIngredients'] as $iid){$_SERVER['REQUEST_URI']='/gewuerz/'.$iid.'/';$c=mk_public_context();check($c['status']===200,'new ingredient route');check(str_contains(mk_public_body($c),$c['item']['sources'][0]['url']),'ingredient evidence');}
$catalog=mk_shop_catalog();check($catalog['checkoutEnabled']===false,'checkout disabled');foreach($catalog['products'] as $p)foreach($p['variants'] as $v)check($v['priceGross']===null,'no fabricated price');
$db=mk_commerce_db();$guest=mk_commerce_session($db);check(!$guest['user_id'],'guest');$session=mk_commerce_dispatch($db,$guest,'session',[]);check($session['checkoutEnabled']===false&&strlen($session['csrf'])===64,'session policy');
foreach(['checkout','pay','order','purchase'] as $action){try{mk_commerce_dispatch($db,$guest,$action,['checkoutEnabled'=>true]);throw new RuntimeException('checkout should fail');}catch(DomainException $e){check(str_contains($e->getMessage(),'gesperrt'),'checkout blocked');}}
$testPassword=bin2hex(random_bytes(12));$registered=mk_commerce_dispatch($db,$guest,'register',['email'=>'qa@example.invalid','password'=>$testPassword,'acknowledgeTest'=>true]);check($registered['user']['id']>0,'registration');$hash=$db->query('SELECT password_hash FROM mk_shop_users')->fetchColumn();check($hash!==$testPassword&&password_verify($testPassword,$hash),'password hashed');
$auth=$db->query('SELECT * FROM mk_shop_sessions WHERE user_id IS NOT NULL')->fetch(PDO::FETCH_ASSOC);$data=['schema'=>1,'shop'=>['cart'=>[],'shelf'=>[],'history'=>[]],'atlas'=>['pantry'=>[],'saved'=>[]],'labels'=>[]];mk_commerce_dispatch($db,$auth,'save',['state'=>$data]);$loaded=mk_commerce_dispatch($db,$auth,'load',[]);check($loaded['state']===$data,'state roundtrip');
try{mk_commerce_dispatch($db,$guest,'load',[]);throw new RuntimeException('guest read should fail');}catch(DomainException $e){}
try{mk_commerce_dispatch($db,$guest,'register',['email'=>'person@real.example','password'=>$testPassword,'acknowledgeTest'=>true]);throw new RuntimeException('real address should fail');}catch(InvalidArgumentException $e){}
$guest2=mk_commerce_session($db);$login=mk_commerce_dispatch($db,$guest2,'login',['email'=>'qa@example.invalid','password'=>$testPassword]);check($login['user']['id']===$registered['user']['id'],'login');
$auth2=$db->query('SELECT * FROM mk_shop_sessions WHERE user_id IS NOT NULL')->fetch(PDO::FETCH_ASSOC);mk_commerce_dispatch($db,$auth2,'delete-account',[]);check((int)$db->query('SELECT COUNT(*) FROM mk_shop_users')->fetchColumn()===0,'test erasure');check((int)$db->query('SELECT COUNT(*) FROM mk_shop_state')->fetchColumn()===0,'state erasure');
echo json_encode(['status'=>'PASS','php'=>PHP_VERSION,'checks'=>['SSR routes and metadata','404 handling','private noindex','no invented prices','server payment gate','guest session','demo registration and login','password hash','authenticated state roundtrip','guest denied','real email denied in demo','test account erasure']]);
